head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellChecked]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 체크 상태를 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 체크 상태를 조회할 Cell 의 Column ID 를 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="columnInfo 파라미터에 checkbox Column ID(chk, trueValue=1 / falseValue=0)를 설정하여 해당 Cell 의 체크 상태를 조회합니다. (chk=1 인 Row 는 true, chk=0 인 Row 는 false)"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - chk : checkbox 컬럼 원본값 (1/0 혼합)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "chk": "1", "name": "John", "dept": "Sales" },
        { "chk": "0", "name": "Jane", "dept": "Dev"   },
        { "chk": "1", "name": "Mike", "dept": "Sales" },
        { "chk": "0", "name": "Amy",  "dept": "Dev"   }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 3컬럼 - chk(checkbox) / name / dept)
    // chk : inputType="checkbox" trueValue="1" falseValue="0"
    // 마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getCellChecked 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="체크"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // chk : inputType="checkbox" - 원본값 1/0, trueValue/falseValue 로 체크 상태 결정
    strTarget += '<w2:column width="120" style="" inputType="checkbox" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getCellChecked 확인 : par_rowIndex / par_columnInfo(Column ID) 로 호출 -> 해당 Cell 의 체크 상태(true/false) 반환
// - chk Column 의 데이터값이 trueValue("1") 와 일치하면 true, falseValue("0") 이면 false
scwin.btn_getCellChecked_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // columnInfo 는 Column ID(String) 로 전달
    let colId = par_columnInfo.getValue();
    let rtn = target1.getCellChecked(rowIndex, colId);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellChecked(" + rowIndex + ", '" + colId + "') : " + rtn);
}
